// ignore_for_file: prefer_const_constructors
// 🖼️ RASMLI TEST RO'YXATI — barcha so'zlar (avto-generatsiya + qo'lda qo'shish mumkin)
// Generator: dart tools/gen_picture_words.dart
//
// ➕ YANGI SAVOL QO'SHISH (asosiy dastur logikasini o'zgartirish SHART EMAS):
//   1) Rasmni `assets/picture_quiz/` papkasiga tashlang.
//      Nom: inglizcha so'z kichik harfda, bo'shliq o'rniga '-'.
//      Masalan: `green-apple.png`, `computer-mouse.png`.
//      O'lcham tavsiyasi: 800x600 px, .png, 100-300 KB.
//   2) Quyidagi ro'yxatga 1 qator qo'shing:
//      PictureWord(english: 'green apple', uzbek: 'yashil olma',
//        imagePath: 'assets/picture_quiz/green-apple.png', emoji: '🍏', category: 'Meva'),
//   3) Tayyor! Test avtomatik ravishda yangi savolni aralashtirib beradi
//      (10 savol, 4 variant, avtomatik o'tish, ⭐ saqlash — o'zgarishsiz ishlaydi).
//
// Har bir so'z emoji-zaxira bilan ishlaydi: agar imagePath dagi fayl
// topilmasa — katta emoji ko'rsatiladi, xatolik chiqmaydi.
// pubspec.yaml da `assets/picture_quiz/` papkasi ro'yxatda — alohida fayl
// qo'shish shart emas, papkadagi barcha rasmlar avtomatik ulanadi.

class PictureWord {
  final String english;
  final String uzbek;
  final String imagePath;
  final String emoji;
  final String category;
  // Cloudflare R2 dagi rasm URL (bo'sh bo'lsa — lokal asset/emoji ishlaydi).
  final String imageUrl;

  const PictureWord({
    required this.english,
    required this.uzbek,
    required this.imagePath,
    required this.emoji,
    required this.category,
    this.imageUrl = '',
  });

  factory PictureWord.fromJson(Map<String, dynamic> j, String imageBase, [String version = '']) {
    final english = (j['english'] ?? '').toString();
    final file = (j['file'] ?? '').toString();
    String localPath = 'assets/picture_quiz/$file';
    if (file.toLowerCase().endsWith('.png')) {
      // Lokal assetlar .png, serverda .jpg bo'lishi mumkin — ikkalasini ham sinaymiz
      localPath = 'assets/picture_quiz/$file';
    }
    String net = '';
    if (file.isNotEmpty && imageBase.isNotEmpty) {
      final f = file.replaceAll(RegExp(r'\.png$', caseSensitive: false), '.jpg');
      net = '$imageBase/images/$f';
      // Cache-busting: admin "Saqlash" bosganda updatedAt o'zgaradi,
      // URL ham o'zgaradi (?v=...) va telefon yangi rasmni yuklaydi.
      // Bo'lmasa bir xil nomdagi yangi rasm o'rniga eski kesh ko'rinaveradi.
      if (version.isNotEmpty) net += '?v=${Uri.encodeComponent(version)}';
    } else if ((j['imageUrl'] ?? '').toString().isNotEmpty) {
      net = (j['imageUrl']).toString();
    }
    return PictureWord(
      english: english,
      uzbek: (j['uzbek'] ?? '').toString(),
      imagePath: localPath,
      emoji: (j['emoji'] ?? '🖼️').toString(),
      category: (j['category'] ?? 'Umumiy').toString(),
      imageUrl: net,
    );
  }
}

