  'Hayvon',
];

/// Rasmli testga kirmaydigan mavhum kategoriyalar.
const List<String> excludedPictureCategories = [
  'Kundalik',
  "Fe'l",
  'Sifat',
];

/// Faqat aniq rasmlardan iborat filtrlangan ro'yxat.
/// null/bo'sh kategoriya so'ralganda shu ishlatiladi.
List<PictureWord> get concretePictureWords =>
    pictureWords.where((w) => pictureCategories.contains(w.category)).toList();

/// Berilgan kategoriyalar ichidan faqat rasmli testga yaroqlisini qoldirish.
/// Masalan: ['Meva', "Fe'l"] -> ['Meva']
List<String>? sanitizePictureCategories(List<String>? cats) {
  if (cats == null || cats.isEmpty) return null;
  final ok = cats.where((c) => pictureCategories.contains(c)).toList();
  if (ok.isEmpty) return null;
  return ok;
}

int pictureCountFor(List<String>? cats) {
  final sanitized = sanitizePictureCategories(cats);
  if (sanitized == null) return concretePictureWords.length;
  return pictureWords.where((w) => sanitized.contains(w.category)).length;
}
